import { describe, expect, it } from 'vitest';
import {
  APP_CAPABILITIES_BASELINE,
  BUSINESS_LOCALE_CODES,
  LAUNCH_COUNTRY_CODES,
  LAUNCH_CURRENCY_CODES,
  LAUNCH_MARKETS,
} from '@margincook/types';

describe('국제 출시 계약 기준선', () => {
  it('5개국·5개 통화·5개 업무 로케일을 일대일로 소유한다', () => {
    expect(Object.keys(LAUNCH_MARKETS)).toEqual(LAUNCH_COUNTRY_CODES);
    expect(Object.values(LAUNCH_MARKETS).map((market) => market.currencyCode)).toEqual(LAUNCH_CURRENCY_CODES);
    expect(Object.values(LAUNCH_MARKETS).map((market) => market.businessLocaleCode)).toEqual(BUSINESS_LOCALE_CODES);
  });

  it('앱 언어를 시장 metadata에 넣지 않는다', () => {
    for (const market of Object.values(LAUNCH_MARKETS)) expect(market).not.toHaveProperty('defaultAppLanguage');
  });

  it('KRW만 0자리이고 나머지 출시 통화는 2자리다', () => {
    expect(LAUNCH_MARKETS.KR.minorUnit).toBe(0);
    for (const code of ['US', 'GB', 'AU', 'CA'] as const) expect(LAUNCH_MARKETS[code].minorUnit).toBe(2);
  });

  it('INTL-1A에서는 국제 세금 읽기·쓰기를 활성화하지 않는다', () => {
    expect(APP_CAPABILITIES_BASELINE).toEqual({
      contractVersion: 1,
      minimumSupportedAppVersion: '0.1.0',
      internationalTax: {
        contractVersion: 'international_tax_v1',
        readEnabled: false,
        writeEnabled: false,
        minimumWriteAppVersion: null,
      },
    });
  });
});

/** INTL-1A TypeScript 기준선과 살아 있는 DB `app_capabilities()` 응답을 직접 대조한다. */
import { describe, expect, it } from 'vitest';
import { spawnSync } from 'node:child_process';
import { APP_CAPABILITIES_BASELINE } from '@margincook/types';

const DB = process.env.MARGINCOOK_PARITY_DB;
const CT = process.env.SUPABASE_DB_CONTAINER ?? 'supabase_db_margincook';

function queryCapabilities(): unknown {
  const result = spawnSync(
    'docker',
    ['exec', '-i', CT, 'psql', '-U', 'postgres', '-d', DB!, '-v', 'ON_ERROR_STOP=1', '-At', '-c',
      'select public.app_capabilities()::text'],
    { encoding: 'utf8' },
  );
  if (result.status !== 0) throw new Error(`psql 실패: ${result.stderr}`);
  return JSON.parse(result.stdout.trim());
}

const dbDescribe = DB ? describe : describe.skip;

dbDescribe(`app_capabilities(DB=${DB ?? '없음'}) ↔ TypeScript 기준선`, () => {
  it('서버와 공용 타입이 같은 판본·최소 버전·비활성 상태다', () => {
    const raw = queryCapabilities() as Record<string, unknown>;
    const tax = raw.international_tax as Record<string, unknown>;
    expect({
      contractVersion: raw.contract_version,
      minimumSupportedAppVersion: raw.minimum_supported_app_version,
      internationalTax: {
        contractVersion: tax.contract_version,
        readEnabled: tax.read_enabled,
        writeEnabled: tax.write_enabled,
        minimumWriteAppVersion: tax.minimum_write_app_version,
      },
    }).toEqual(APP_CAPABILITIES_BASELINE);
  });
});

if (!DB) {
  it('MARGINCOOK_PARITY_DB가 없어 살아 있는 DB 대조는 건너뛴다 (verify ④가 실행한다)', () => {
    expect(true).toBe(true);
  });
}

/**
 * P1-1 원격 ACL audit의 실제 DB·모바일 RPC 허용 목록 회귀시험.
 *
 * 배포 audit 자체는 현재 미승인 authenticated RPC를 실패시킨다. 이 시험은 그 위험을
 * 성공으로 바꾸지 않고, 새 DB에서 SQL이 끝까지 실행되어 정확한 metric을 한 번씩 내며
 * 이미 닫힌 사후조건 값을 유지하는지를 잰다. 프로브 rollback과 모바일 .rpc 호출 이름↔허용 목록의
 * 양방향 일치도 확인하며, 대조할 수 없는 동적 .rpc 이름은 허용하지 않는다.
 */
import { readFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { scanMobileRpcNames } from './admin-acl-source-scan.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, '..', '..', '..');
const SQL_PATH = join(HERE, 'admin-acl-audit.sql');
const MOBILE_ROOTS = [
  join(ROOT, 'apps', 'mobile', 'src'),
  join(ROOT, 'apps', 'mobile', 'app'),
];
const CONTAINER = process.env.SUPABASE_DB_CONTAINER ?? 'supabase_db_margincook';
const DATABASE = process.argv[2] ?? process.env.PGDATABASE;

if (!/^[A-Za-z0-9_.-]{1,128}$/.test(CONTAINER)) {
  console.error('SUPABASE_DB_CONTAINER 형식이 아닙니다');
  process.exit(2);
}
if (!DATABASE || !/^[a-z_][a-z0-9_]{0,62}$/.test(DATABASE)) {
  console.error('사용법: node packages/db/scripts/admin-acl-audit.test.mjs <DB 식별자>');
  process.exit(2);
}

const EXPECTED_METRICS = new Map([
  ['migrations', 'expected=2'],
  ['probe_owner', 'expected=postgres'],
  ['probe_dangerous', 'expected=0'],
  ['public_dangerous', 'expected=0'],
  ['rls_disabled_app_tables', 'expected=0'],
  ['protected_objects', 'expected=6'],
  ['protected_writes', 'expected=0'],
  ['ledger_write_paths', 'expected=0'],
  ['source_schema_grants', 'expected=0'],
  ['supabase_admin_objects', 'expected=0'],
  ['anon_rpc', 'expected=0'],
  ['blocked_internal_rpc', 'expected=0'],
  ['blocked_internal_rpc_objects', 'expected=11'],
  ['rpc_executor_role', 'expected=1'],
  ['rpc_executor_facades_invalid', 'expected=0'],
  ['rpc_executor_privileged_maintenance', 'expected=0'],
  ['rls_policy_helper_calls', 'expected=0'],
  ['facade_rpc_objects', 'expected=66'],
  ['facade_rpc_missing', 'expected=0'],
  ['unapproved_authenticated_rpc', 'expected=0'],
  ['platform_default_open', 'informational'],
]);

function fail(message) {
  console.error(`admin-acl audit 회귀시험 실패: ${message}`);
  process.exit(1);
}

function psql(input) {
  const result = spawnSync(
    'docker',
    ['exec', '-i', CONTAINER, 'psql', '-U', 'postgres', '-d', DATABASE, '-v', 'ON_ERROR_STOP=1', '-q', '-t', '-A'],
    { input, encoding: 'utf8' },
  );
  if (result.status !== 0) fail(`${result.stderr || result.stdout || 'psql 실행 실패'}`.trim());
  return String(result.stdout ?? '');
}

function auditSqlWithAllowlistExports(sql) {
  const finalRollback = /rollback;\s*$/i.exec(sql);
  if (!finalRollback) fail('감사 SQL의 마지막 rollback을 찾지 못했습니다');
  const beforeRollback = sql.slice(0, finalRollback.index);
  return `${beforeRollback}
select '__acl_approved_rpc|' || signature from _acl_approved_rpc order by signature;
select '__acl_non_mobile_rpc|' || signature || '|' || consumer
  from _acl_non_mobile_rpc order by signature;
rollback;
`;
}

function difference(left, right) {
  return [...left].filter((value) => !right.has(value)).sort();
}

const sql = readFileSync(SQL_PATH, 'utf8');
const raw = psql(`set search_path to pg_catalog;\n${auditSqlWithAllowlistExports(sql)}`);
const outputLines = raw.split(/\r?\n/).filter(Boolean);
const approvedSignatures = outputLines
  .filter((line) => line.startsWith('__acl_approved_rpc|'))
  .map((line) => line.slice('__acl_approved_rpc|'.length));
const nonMobileRows = outputLines
  .filter((line) => line.startsWith('__acl_non_mobile_rpc|'))
  .map((line) => line.split('|'));
const nonMobileSignatures = nonMobileRows.map(([, signature]) => signature);
const rows = outputLines
  .filter((line) => !line.startsWith('__acl_approved_rpc|') && !line.startsWith('__acl_non_mobile_rpc|'))
  .map((line) => line.split('|'));
const seen = new Map();

for (const [metric, value, expected, ...extra] of rows) {
  if (!metric || value === undefined || expected === undefined || extra.length) fail(`잘못된 metric 행: ${[metric, value, expected, ...extra].join('|')}`);
  if (seen.has(metric)) fail(`중복 metric: ${metric}`);
  seen.set(metric, { value, expected });
}
for (const [metric, expected] of EXPECTED_METRICS) {
  if (!seen.has(metric)) fail(`누락 metric: ${metric}`);
  if (seen.get(metric).expected !== expected) fail(`${metric} 기대 설명 불일치: ${seen.get(metric).expected}`);
}
for (const metric of seen.keys()) if (!EXPECTED_METRICS.has(metric)) fail(`알 수 없는 metric: ${metric}`);
if (seen.get('probe_owner').value !== 'postgres') fail(`프로브 소유자: ${seen.get('probe_owner').value}`);
if (seen.get('facade_rpc_missing').value !== '0') fail(`허용 facade가 DB에 없습니다: ${seen.get('facade_rpc_missing').value}`);

// 새 DB가 이미 만족하는 사후조건은 값까지 고정해 후속 migration의 GRANT·RLS 회귀를 즉시 잡는다.
const FRESH_DB_VALUES = new Map([
  ['probe_dangerous', '0'],
  ['public_dangerous', '0'],
  ['rls_disabled_app_tables', '0'],
  ['protected_objects', '6'],
  ['protected_writes', '0'],
  ['source_schema_grants', '0'],
  ['supabase_admin_objects', '0'],
  ['anon_rpc', '0'],
  ['blocked_internal_rpc', '0'],
  ['blocked_internal_rpc_objects', '11'],
  ['rpc_executor_role', '1'],
  ['rpc_executor_facades_invalid', '0'],
  ['rpc_executor_privileged_maintenance', '0'],
  ['rls_policy_helper_calls', '0'],
  ['facade_rpc_objects', '66'],
]);
for (const [metric, expectedValue] of FRESH_DB_VALUES) {
  const observed = seen.get(metric).value;
  if (observed !== expectedValue) fail(`${metric} 사후조건 불일치: 관측=${observed} 기대=${expectedValue}`);
}

// CLI 장부가 없으면 0만, 있으면 0166·0167 둘 모두를 의미하는 2만 허용한다.
const migrationLedger = psql("select case when to_regclass('supabase_migrations.schema_migrations') is null then 'absent' else 'present' end;").trim();
const expectedMigrations = migrationLedger === 'present' ? '2' : '0';
if (seen.get('migrations').value !== expectedMigrations) {
  fail(`migrations 값이 하네스 계약 밖입니다: 관측=${seen.get('migrations').value} 장부=${migrationLedger} 기대=${expectedMigrations}`);
}

const probe = psql("select coalesce(to_regclass('public._acl_probe_postgres')::text, 'absent');").trim();
if (probe !== 'absent') fail(`rollback 뒤 프로브가 남았습니다: ${probe}`);

if (approvedSignatures.length === 0) fail('허용 RPC 시그니처를 하나도 추출하지 못했습니다');
if (new Set(approvedSignatures).size !== approvedSignatures.length) fail('허용 RPC 시그니처가 중복됐습니다');
if (nonMobileRows.some((row) => row.length !== 3 || !row[1] || !row[2])) fail('비-mobile RPC 출력 형식이 잘못됐습니다');
const approvedNames = new Set(approvedSignatures.map((signature) => signature.slice(0, signature.indexOf('('))));
if (approvedNames.has('comment_only_rpc')) fail('SQL 주석을 허용 RPC로 잘못 읽었습니다');
const nonMobileNames = new Set(nonMobileSignatures.map((signature) => signature.slice(0, signature.indexOf('('))));
const strayNonMobile = difference(nonMobileNames, approvedNames);
if (strayNonMobile.length) fail(`비-mobile 예외가 허용 목록에 없습니다: ${strayNonMobile.join(', ')}`);
const expectedMobileNames = new Set([...approvedNames].filter((name) => !nonMobileNames.has(name)));
let sourceNames;
try {
  sourceNames = scanMobileRpcNames(MOBILE_ROOTS);
} catch (error) {
  fail(error instanceof Error ? error.message : String(error));
}
const missingFromAllowlist = difference(sourceNames, expectedMobileNames);
const unusedAllowlist = difference(expectedMobileNames, sourceNames);
if (missingFromAllowlist.length || unusedAllowlist.length) {
  fail(`모바일 RPC↔허용 목록 불일치 — 미허용=[${missingFromAllowlist.join(', ')}] 미사용=[${unusedAllowlist.join(', ')}]`);
}

// P0-5 이후에는 부채 상한이 아니라 0이 계약이다. 하나라도 다시 열리면 즉시 실패한다.
for (const metric of ['ledger_write_paths', 'unapproved_authenticated_rpc']) {
  const observed = seen.get(metric).value;
  if (observed !== '0') fail(`${metric} 최소 권한 회귀: 관측=${observed} 기대=0`);
}

console.log(`admin-acl audit 실제 DB 계약 통과 — metric ${seen.size}개 · 모바일 RPC ${sourceNames.size}개 · 비-mobile 예외 ${nonMobileNames.size}개`);
console.log(`  관측값: rls_disabled_app_tables=${seen.get('rls_disabled_app_tables').value} ledger_write_paths=${seen.get('ledger_write_paths').value} unapproved_authenticated_rpc=${seen.get('unapproved_authenticated_rpc').value}`);

-- 0178 · 국제 출시의 계약·capability 기준선만 먼저 배포한다.
--
-- 현행 tax_of()/save_store_tax()/판매·손익 계산은 0090의 유효 세율 계약을 그대로 쓴다.
-- 국제 세금 읽기·쓰기는 둘 다 false이며, 이 migration은 시장/세금 프로필이나 금액 원장을 만들지 않는다.

begin;

create or replace function public.app_capabilities()
returns jsonb
language sql
stable
set search_path = pg_catalog, public
as $$
  select jsonb_build_object(
    'contract_version', 1,
    'minimum_supported_app_version', '0.1.0',
    'international_tax', jsonb_build_object(
      'contract_version', 'international_tax_v1',
      'read_enabled', false,
      'write_enabled', false,
      'minimum_write_app_version', null
    )
  )
$$;

revoke execute on function public.app_capabilities() from public, anon;
grant execute on function public.app_capabilities() to authenticated, service_role;

comment on function public.app_capabilities() is
  '앱 계약 기준선. 0178에서는 국제 세금 읽기·쓰기를 활성화하지 않고 최소 지원 앱 버전만 공개한다.';

do $verify$
declare v jsonb := public.app_capabilities();
begin
  if v is distinct from jsonb_build_object(
    'contract_version', 1,
    'minimum_supported_app_version', '0.1.0',
    'international_tax', jsonb_build_object(
      'contract_version', 'international_tax_v1',
      'read_enabled', false,
      'write_enabled', false,
      'minimum_write_app_version', null
    )
  ) then
    raise exception '0178: 앱 capability 응답 계약이 다릅니다';
  end if;

  if has_function_privilege('anon', 'public.app_capabilities()', 'execute')
     or not has_function_privilege('authenticated', 'public.app_capabilities()', 'execute')
     or not has_function_privilege('service_role', 'public.app_capabilities()', 'execute') then
    raise exception '0178: app_capabilities 실행 권한이 맞지 않습니다';
  end if;
end;
$verify$;

commit;

-- ═══════════════════════════════════════════════════════════════
-- 34 · 앱 롤은 공식 RPC만 실행하고 원장·내부 몸통을 직접 건드리지 못한다
--
-- 기존 01~33은 내부 공식까지 재는 백색상자 시험이라 margincook_rpc_executor로 돈다.
-- 이 파일은 실제 Data API 역할(authenticated)로 전환해 외부 공격면을 따로 잰다.
-- ═══════════════════════════════════════════════════════════════

-- ── 1. 전용 실행 역할은 로그인·RLS 우회·앱의 SET ROLE 경로가 없다 ──────────────

select pg_temp.ok('RPC 실행 역할은 로그인할 수 없다', not (
  select rolcanlogin from pg_roles where rolname = 'margincook_rpc_executor'));
select pg_temp.ok('RPC 실행 역할은 authenticated 권한을 상속한다',
  pg_has_role('margincook_rpc_executor', 'authenticated', 'member'));
select pg_temp.ok('authenticated는 RPC 실행 역할로 전환할 수 없다', not
  pg_has_role('authenticated', 'margincook_rpc_executor', 'member'));

select pg_temp.eq('authenticated에 열린 public 함수는 공식 facade 66개뿐이다', (
  select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.prokind in ('f', 'p')
     and has_function_privilege('authenticated', p.oid, 'execute'))::numeric, 66);

select pg_temp.ok('RLS 정책은 닫힌 my_store_ids 몸통을 호출하지 않는다', not exists (
  select 1 from pg_policy pol
   where coalesce(pg_get_expr(pol.polqual, pol.polrelid), '') like '%my_store_ids()%'
      or coalesce(pg_get_expr(pol.polwithcheck, pol.polrelid), '') like '%my_store_ids()%'));

-- purge_archived_store는 예약이 없으면 몸통이 스스로 42501(PURGE_NOT_SCHEDULED)을
-- 던지므로 권한 판별력이 없다. 자체 42501이 없는 유지보수 문으로 권한 거부를 잰다.
select pg_temp.raises('RPC 실행 역할은 전 매장 자동 마감 스윕을 부를 수 없다',
  'select close_due_business_days()', '42501');
select pg_temp.raises('RPC 실행 역할은 전 매장 변경 이력 청소를 부를 수 없다',
  'select purge_entity_changes()', '42501');
select pg_temp.ok('RPC 실행 역할에 매장 삭제 몸통 EXECUTE가 없다', not
  has_function_privilege('margincook_rpc_executor',
    'public.purge_archived_store(uuid,text)', 'execute'));

select pg_temp.eq('RPC 실행 역할에 postgres 유지보수 definer가 열린 건수는 0이다', (
  select count(*)
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    join pg_roles owner_role on owner_role.oid = p.proowner
   where n.nspname = 'public' and p.prokind in ('f', 'p') and p.prosecdef
     and owner_role.rolname = 'postgres'
     and has_function_privilege('margincook_rpc_executor', p.oid, 'execute')
     and not has_function_privilege('authenticated', p.oid, 'execute')
)::numeric, 0);

-- RLS가 실제로 다른 사장님의 매장을 숨기는지 재기 위한 두 번째 매장.
do $t$
declare
  v_owner uuid;
  v_store uuid;
  v_ingredient uuid;
begin
  v_owner := pg_temp.new_owner();
  perform pg_temp.as_owner(v_owner);
  v_store := (create_store('P0-5 다른 사장님', 'Asia/Seoul')->>'store_id')::uuid;
  perform set_config('margincook.test.foreign_store', v_store::text, true);
  v_ingredient := save_ingredient(v_store, jsonb_build_object(
    'name', 'P0-5 다른 매장 식재료', 'base_unit', 'g', 'per_volume', 1,
    'safety_stock', 0, 'min_order_qty', 1));
  perform set_config('margincook.test.foreign_ingredient', v_ingredient::text, true);
  perform pg_temp.as_owner(pg_temp.owner());
end
$t$;

-- 여기부터는 백색상자 역할이 아니라 앱의 실제 PostgREST 역할이다.
set local role authenticated;

-- ── 2. 승인된 읽기·쓰기 facade는 정상 동작하고 RLS는 유지된다 ───────────────

select pg_temp.ok('공식 읽기 RPC get_settings는 열린다',
  (get_settings(pg_temp.store())->>'revision')::integer >= 1);

do $t$
declare
  v_category uuid;
  v_before bigint;
  v_after bigint;
begin
  v_category := save_category(
    pg_temp.store(),
    jsonb_build_object('name', 'P0-5 공식 문 시험 ' || gen_random_uuid(), 'sort_order', 999)
  );
  perform pg_temp.ok('공식 쓰기 RPC save_category는 열린다', exists (
    select 1 from categories where id = v_category and store_id = pg_temp.store()));

  select count(*) into v_before from inventory_events where ingredient_id = pg_temp.ing('대파');
  perform e5_stock_adjusted(pg_temp.ing('대파'), 4321, false, 'P0-5 공식 원장 문');
  select count(*) into v_after from inventory_events where ingredient_id = pg_temp.ing('대파');
  perform pg_temp.eq('공식 원장 RPC는 이벤트 한 줄을 추가한다', v_after, v_before + 1);
  perform pg_temp.eq('공식 원장 RPC가 확정 잔액도 맞춘다',
    (select stock_total from inventory_states where ingredient_id = pg_temp.ing('대파')), 4321);
end
$t$;

